alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.meta enable row level security;
alter table public.categories enable row level security;
alter table public.suppliers enable row level security;
alter table public.products enable row level security;
alter table public.product_units enable row level security;
alter table public.stock_batches enable row level security;
alter table public.stock_movements enable row level security;
alter table public.audit_logs enable row level security;
alter table public.product_relations enable row level security;
alter table public.kits enable row level security;
alter table public.kit_items enable row level security;
alter table public.custom_field_definitions enable row level security;
alter table public.settings enable row level security;
alter table public.sync_queue enable row level security;

create policy workspaces_select on public.workspaces for select to authenticated using (public.is_workspace_member(id));
create policy workspaces_insert on public.workspaces for insert to authenticated with check (auth.uid() is not null);
create policy workspaces_update on public.workspaces for update to authenticated using (public.workspace_role(id) in ('owner','editor')) with check (public.workspace_role(id) in ('owner','editor'));
create policy workspaces_delete on public.workspaces for delete to authenticated using (public.workspace_role(id) = 'owner');

create policy members_select on public.workspace_members for select to authenticated using (user_id = auth.uid() or public.is_workspace_member(workspace_id));
create policy members_insert on public.workspace_members for insert to authenticated with check (public.workspace_role(workspace_id) = 'owner');
create policy members_update on public.workspace_members for update to authenticated using (public.workspace_role(workspace_id) = 'owner') with check (public.workspace_role(workspace_id) = 'owner');
create policy members_delete on public.workspace_members for delete to authenticated using (public.workspace_role(workspace_id) = 'owner');

create policy meta_select on public.meta for select to authenticated using (user_id = auth.uid());
create policy meta_insert on public.meta for insert to authenticated with check (user_id = auth.uid());
create policy meta_update on public.meta for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy meta_delete on public.meta for delete to authenticated using (user_id = auth.uid());

create policy categories_select on public.categories for select to authenticated using (public.is_workspace_member(workspace_id));
create policy categories_insert on public.categories for insert to authenticated with check (public.workspace_role(workspace_id) in ('owner','editor'));
create policy categories_update on public.categories for update to authenticated using (public.workspace_role(workspace_id) in ('owner','editor')) with check (public.workspace_role(workspace_id) in ('owner','editor'));
create policy categories_delete on public.categories for delete to authenticated using (public.workspace_role(workspace_id) = 'owner');
