create policy settings_insert on public.settings for insert to authenticated with check (user_id = auth.uid() and public.workspace_role(workspace_id) in ('owner','editor'));
create policy settings_update on public.settings for update to authenticated using (user_id = auth.uid() and public.workspace_role(workspace_id) in ('owner','editor')) with check (user_id = auth.uid() and public.workspace_role(workspace_id) in ('owner','editor'));
